// tick 会话逐步提交的字段（叙述、下轮计划、决定、产出），合并进草稿
'tick-field': {
  path: (seq) => PATHS.tickDraft(seq),
  mode: 'merge',
  validate(data) {
    mustObject(data, 'tick 字段');
    const allowed = ['narrative', 'next_plan', 'decisions', 'outputs', 'artifacts'];
    const keys = Object.keys(data);
    if (keys.length === 0) throw new Error('tick 字段至少要提交一项（narrative/next_plan/decisions/outputs/artifacts）');
    for (const k of keys) {
      if (!allowed.includes(k)) throw new Error(`tick 字段不认识 ${k}，只收 narrative/next_plan/decisions/outputs/artifacts`);
    }
    if ('narrative' in data) mustNonEmptyString(data.narrative, 'narrative（本轮叙述）');
    if ('next_plan' in data) mustNonEmptyString(data.next_plan, 'next_plan（下轮计划）');
    if ('decisions' in data) mustArray(data.decisions, 'decisions（本轮决定）');
    if ('outputs' in data) mustArray(data.outputs, 'outputs（本轮产出）');
    // artifacts：本轮产出对应的 artifact id 列表（与 outputs 正交，不改 outputs 的既有形状），
    // 供 hub 的「本轮产出 chips」跨引 artifact 画廊——每项必须是字符串（id），不许夹带别的类型。
    if ('artifacts' in data) {
      mustArray(data.artifacts, 'artifacts（本轮产出的 artifact id）');
      data.artifacts.forEach((item, i) => {
        mustNonEmptyString(item, `artifacts 第 ${i + 1} 项（artifact id）`);
      });
    }
  }
},
// 请示（不可逆有损动作等）
'approval': {
  path: (id) => `approvals/${id}.json`,
  mode: 'overwrite',
  validate(data) {
    mustObject(data, '请示');
    mustNonEmptyString(data.type, 'type（请示类型）');
    mustNonEmptyString(data.title, 'title（一句话请示：要老板做的那一件事，祈使句）');
    // 正文条理化（老板要「条理清晰、不要一长段话」）：新写法拆成结构化几格——
    //   background（背景，为什么要拍板）＋可选 impact（影响，不拍会怎样）；
    //   旧写法的 detail（一整段说明）仍收，作向后兼容/自由补充。至少要有 background 或 detail，别交白卷；
    //   带了 background/impact/detail 的就不许是空串。UI 优先分段渲染 background/impact，缺了才回落 detail。
    const 有正文 = (v) => typeof v === 'string' && v.trim() !== '';
    if (!有正文(data.background) && !有正文(data.detail)) {
      throw new Error('请示正文缺失：至少写 background（背景，为什么要拍板）或 detail（白话说明）');
    }
    for (const [key, label] of [
      ['background', 'background（背景）'],
      ['impact', 'impact（影响）'],
      ['detail', 'detail（白话说明）']
    ]) {
      if (data[key] !== undefined && !有正文(data[key])) {
        throw new Error(`${label} 要么不带，要么是非空文字`);
      }
    }
    // 老板第二次投诉同一件事（2026-07-17）：「审批的内容非常不白话、没有任何格式感，
    // 我都不懂他想让我干什么」。上一版只加了结构化字段就指望 AI 分格写——AI 照样把整堵墙
    // 塞进 background。这次上量得出来的闸：请示是老板**唯一**要动手的地方，四格全过
    // 「不许机器话」＋「不许一长段」。
    for (const [key, label] of [
      ['title', 'title（一句话请示）'],
      ['background', 'background（背景）'],
      ['impact', 'impact（影响）'],
      ['detail', 'detail（白话说明）']

